
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_bmk_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_bmk", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.289796801512578e+00, -2.258089496637488e+00, -2.214033690138272e+00, -2.153568759654565e+00, -2.071621734071929e+00, -1.961032848537154e+00, -1.808089299111948e+00, -1.583812539317765e+00, -1.271294339243057e+00, -9.628027224961343e-01, -6.050110920412219e-01, -3.923416315481669e-01, -3.091060127804460e-01, -2.881672867562021e-01, -2.203423234819440e-01, -1.382068956885085e-01, -8.648734427347118e-02, -8.145641168465437e-02, -2.106466747226121e-02, -2.389674151319421e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


